{"cards": [{"node_code": "N_c0aec120e9124ed4", "definition": "纵隔疾病是研究位于两肺之间、胸骨后方及脊柱前方的纵隔腔内结构（如心脏大血管、气管、食管、胸腺等）的解剖、生理、病理及诊疗的医学分支。", "boundary": "本节点涵盖纵隔肿瘤、胸腺疾病、食管纵隔段病变、纵隔感染及先天性纵隔畸形等。不涵盖肺实质疾病（归肺疾病）、胸膜疾病（归胸膜与胸腔疾病）及膈肌疾病（归膈疾病）。若病变主要累及心脏或大血管且以心血管功能为主，可归心血管系统，但纵隔占位效应或局部结构异常归本节点。", "includes": ["纵隔肿瘤与胸腺疾病", "食管纵隔段及气管纵隔段病变", "纵隔感染、脓肿及先天性畸形"], "excludes": ["肺实质及气道疾病", "胸膜及胸腔积液疾病", "膈肌疾病"], "sibling_distinctions": [{"other_code": "N_85bbf4f0c3e17251", "rule": "肺疾病关注肺实质及肺内气道，纵隔疾病关注肺外纵隔腔内结构；肺门淋巴结肿大若主要影响肺功能归肺疾病，若形成纵隔占位归纵隔疾病。"}, {"other_code": "N_3fd6d142adda6723", "rule": "胸膜与胸腔疾病关注胸膜腔及胸壁，纵隔疾病关注纵隔腔内器官；胸腔积液归胸膜与胸腔疾病，纵隔积液或脓肿归纵隔疾病。"}], "cross_boundary_rule": "涉及食管癌时，若侧重消化道功能及内镜治疗归消化系统，若侧重纵隔侵犯及放疗归纵隔疾病或肿瘤学；涉及胸腺瘤时，若合并重症肌无力需同时关联神经肌肉疾病，但肿瘤本体归纵隔疾病。"}, {"node_code": "N_85bbf4f0c3e17251", "definition": "肺疾病是研究肺实质、肺内气道及肺血管系统的结构功能异常，包括感染、肿瘤、血管病变及间质性病变等病理过程的医学分支。", "boundary": "本节点涵盖肺炎、肺结核、肺癌、肺栓塞、间质性肺病等。不涵盖气道原发病（如哮喘、COPD，归气道疾病）、胸膜疾病（归胸膜与胸腔疾病）及纵隔疾病（归纵隔疾病）。肺血管疾病若由左心衰竭引起归心血管系统，若由肺动脉高压或栓塞引起归本节点。", "includes": ["肺部感染性疾病（细菌、病毒、真菌等）", "肺部肿瘤与肺癌", "肺部血管疾病（肺栓塞、肺动脉高压）", "间质性肺疾病与弥漫性肺疾病"], "excludes": ["气道原发疾病（哮喘、COPD）", "胸膜及胸腔疾病", "纵隔疾病"], "sibling_distinctions": [{"other_code": "N_6f08c89f8177ea4e", "rule": "气道疾病关注气管、支气管等大气道结构及功能，肺疾病关注肺实质及小气道；哮喘、COPD归气道疾病，肺炎、肺癌归肺疾病。"}, {"other_code": "N_c0aec120e9124ed4", "rule": "肺疾病关注肺内结构，纵隔疾病关注肺外纵隔结构；肺门病变若主要影响肺实质归肺疾病，若形成纵隔占位归纵隔疾病。"}], "cross_boundary_rule": "涉及肺栓塞时，若侧重血栓形成机制及全身抗凝归心血管系统，若侧重肺部影像及呼吸支持归肺疾病；涉及肺癌时，若侧重局部手术归外科学（胸外科），若侧重内科治疗归肺疾病或肿瘤学。"}, {"node_code": "N_3fd6d142adda6723", "definition": "胸膜与胸腔疾病是研究胸膜、胸壁及胸腔腔隙的结构功能异常，包括胸膜炎、气胸、胸腔积液及胸壁病变等病理过程的医学分支。", "boundary": "本节点涵盖胸膜炎、气胸、胸腔积液、胸壁肿瘤及创伤等。不涵盖肺实质疾病（归肺疾病）、纵隔疾病（归纵隔疾病）及膈肌疾病（归膈疾病）。胸膜疾病若由肺实质病变继发（如肺炎旁胸腔积液），主挂载仍归肺疾病，但胸腔穿刺引流等操作归本节点。", "includes": ["胸膜炎、气胸及胸腔积液", "胸壁肿瘤、创伤及感染", "胸腔镜手术及胸膜固定术"], "excludes": ["肺实质及气道疾病", "纵隔疾病", "膈肌疾病"], "sibling_distinctions": [{"other_code": "N_85bbf4f0c3e17251", "rule": "肺疾病关注肺实质，胸膜与胸腔疾病关注胸膜腔及胸壁；肺炎归肺疾病，肺炎旁胸腔积液主挂载归肺疾病，但胸腔积液本身归胸膜与胸腔疾病。"}, {"other_code": "N_c0aec120e9124ed4", "rule": "纵隔疾病关注纵隔腔内器官，胸膜与胸腔疾病关注胸膜腔及胸壁；纵隔脓肿归纵隔疾病，胸膜腔脓肿归胸膜与胸腔疾病。"}], "cross_boundary_rule": "涉及胸腔积液时，若由心衰引起归心血管系统，若由肺炎引起归肺疾病，若由胸膜原发病（如胸膜间皮瘤）引起归胸膜与胸腔疾病；涉及气胸时，若由肺大疱破裂引起归肺疾病，若由外伤引起归胸膜与胸腔疾病。"}]}
